define(["editor_tiny/loader","editor_tiny/utils","core/str","./common","./options","./recorder","./configuration"],function(TinyLoader,TinyUtils,Str,Common,Options,Recorder,Configuration){return new Promise(async function(resolve){const values=await Promise.all([TinyLoader.getTinyMCE(),Str.get_string("buttontitle",Common.component),TinyUtils.getButtonImage("screen",Common.component),TinyUtils.getPluginMetadata(Common.component,Common.pluginName)]);const tinyMCE=values[0];const buttonText=values[1];const buttonImage=values[2];const pluginMetadata=values[3];tinyMCE.PluginManager.add(Common.component+"/plugin",function(editor){Options.register(editor);editor.ui.registry.addIcon(Common.buttonIcon,buttonImage.html);editor.ui.registry.addButton(Common.buttonName,{icon:Common.buttonIcon,tooltip:buttonText,onAction:function(){Recorder.openRecorder(editor)}});editor.ui.registry.addMenuItem(Common.buttonName,{icon:Common.buttonIcon,text:buttonText,onAction:function(){Recorder.openRecorder(editor)}});return pluginMetadata});resolve([Common.component+"/plugin",Configuration])})});